const MINI=['marko','pesme','sarac','vila','musa','uros','oranje','ramazan','svadbarina','sablja','soko','smrt','spava','pesma'];
for(const c of CHAPTERS)if(MINI.includes(c.id))c.mini=`assets/ui/minijature/minijatura-${c.id}.webp`;
if(MINI.includes('pesma'))SONG.mini='assets/ui/minijature/minijatura-pesma.webp';
SONG.tab='assets/ui/rukopis-gusle.webp';
globalThis.markoLegende={CHAPTERS,SONG};
